mapper.select:
SELECT SDT.DEVICE_CODE FROM SMT_DEVICE_TASK SDT
AND SDT.CARD_NO = #{query.cardNo}
AND SDT.DEVICE_TYPE = #{query.deviceType}
ORDER BY SDA.ID ASC

SELECT SDT.ID, SDT.CARD_NO, SDT.DEVICE_CODE, SDT.SERVICE_TYPE, SDT.STATUS TASK_TYPE, SDT.GENERAL, SDT.CREATE_TIME, SS.BADGE, SDT.ACTION, SDT.UPDATE_TIME OVER_TIME, SDT.ID TASK_ID, SD.DEVICE_NAME, SD.DEVICE_TYPE, SDT.REMARK, SA.AREA_NAME FROM SMT_DEVICE_TASK SDT LEFT JOIN SMT_STAFF SS ON SDT.CARD_NO = SS."ID" LEFT JOIN SMT_DEVICE SD ON SD.ID = SDT.DEVICE_CODE LEFT JOIN SMT_DEVICE_AREA SDA ON SDA.DEVICE_ID = SD.ID LEFT JOIN SMT_AREA SA ON SA.ID = SDA.AREA_ID
SDT.DEVICE_TYPE = 1
AND SDT.STATUS = #{query.taskType}
AND SDT.ACTION = #{query.action}
AND SDT.DEVICE_CODE = #{query.deviceCode}
AND SDT.GENERAL LIKE CONCAT(CONCAT('%',#{query.general}),'%')
AND SS.BADGE = #{query.badge}
AND SD.DEVICE_TYPE = #{query.deviceType}
AND SA.ID = #{query.areaId}
AND SDT.SERVICE_TYPE = #{query.serviceType}
AND SDT.CREATE_TIME >= TO_DATE(#{query.startTime,jdbcType=DATE}, 'yyyy-MM-dd')
AND SDT.CREATE_TIME < TO_DATE(#{query.endTime,jdbcType=DATE}, 'yyyy-MM-dd') + 1
AND SD.PARK_ID IN
#{tempId}
ORDER BY SDT.CREATE_TIME DESC, SDT.UPDATE_TIME DESC

SELECT
    SDT.ID, SDT.CARD_NO, SDT.DEVICE_CODE, SDT.SERVICE_TYPE,
    SDT.STATUS TASK_TYPE, SDT.GENERAL, SDT.ACTION, SDT.CREATE_TIME,
    SS.BADGE, SDT.UPDATE_TIME OVER_TIME, SD.DEVICE_NAME,
    SD.DEVICE_TYPE, SDT.REMARK, SA.AREA_NAME, SDT.OPT_USER
FROM (
    SELECT * FROM SMT_ISC_DEVICE_TASK
    WHERE DEVICE_TYPE = 1

		AND STATUS = #{query.taskType}


		AND ACTION = #{query.action}


		AND DEVICE_CODE = #{query.deviceCode}


		AND GENERAL LIKE CONCAT(CONCAT('%',#{query.general}),'%')


		AND SERVICE_TYPE = #{query.serviceType}


		AND CREATE_TIME >= TO_DATE(#{query.startTime} || ' 00:00:00', 'yyyy-MM-dd HH24:MI:SS')


		AND CREATE_TIME <= TO_DATE(#{query.endTime} || ' 23:59:59', 'yyyy-MM-dd HH24:MI:SS')

) SDT
LEFT JOIN SMT_DEVICE SD ON SD.ID = SDT.DEVICE_CODE
LEFT JOIN SMT_STAFF SS ON SDT.CARD_NO = SS."ID"
LEFT JOIN SMT_DEVICE_AREA SDA ON SDA.DEVICE_ID = SD.ID
LEFT JOIN SMT_AREA SA ON SA.ID = SDA.AREA_ID

	1=1

		AND SS.BADGE = #{query.badge}


		AND SD.DEVICE_TYPE = #{query.deviceType}


		AND SD.DEVICE_NAME LIKE CONCAT(CONCAT('%',#{query.deviceName}),'%')


		AND SA.ID = #{query.areaId}


		AND SD.PARK_ID IN

			#{tempId}



ORDER BY SDT.CREATE_TIME DESC, SDT.UPDATE_TIME DESC

SELECT V_SDT.CARD_NO, V_SDT.GENERAL, V_SDT.IMAGE_ID FROM ( SELECT ROW_NUMBER () OVER ( PARTITION BY SDT.CARD_NO ORDER BY SDT.CREATE_TIME ) rn, SDT.CARD_NO, SDT.GENERAL, SDT.IMAGE_ID FROM SMT_DEVICE_TASK SDT LEFT JOIN SMT_DEVICE SD ON SDT.DEVICE_CODE = SD."ID"
AND SDT.GENERAL LIKE CONCAT(CONCAT('%',#{query.general}),'%')
AND SD.PARK_ID = #{query.parkId}
AND SD.PARK_ID IN
#{tempId}
AND SDT.DEVICE_TYPE = #{query.deviceType}
AND SDT.STATUS = #{query.status}
ORDER BY SDT.CREATE_TIME DESC ) V_SDT WHERE V_SDT.RN = 1
